RAT=c.ratings||{};POP={};c.bots.forEach((b,i)=>POP[b.id]={rank:i+1});
$('trend').innerHTML=c.trending?`<div class="banner"><span>🏆 <b>Bot of the week:</b> ${esc(c.trending)}</span></div>`:'';
